89	export async function startServer(): Promise<StartedServer> {
90	  let config = loadConfig();
91	  initTelemetry({ enabled: config.telemetryEnabled });
92	  if (process.env.PAPERCLIP_SECRETS_PROVIDER === undefined) {
93	    process.env.PAPERCLIP_SECRETS_PROVIDER = config.secretsProvider;
94	  }
95	  if (process.env.PAPERCLIP_SECRETS_STRICT_MODE === undefined) {
96	    process.env.PAPERCLIP_SECRETS_STRICT_MODE = config.secretsStrictMode ? "true" : "false";
97	  }
98	  if (process.env.PAPERCLIP_SECRETS_MASTER_KEY_FILE === undefined) {
99	    process.env.PAPERCLIP_SECRETS_MASTER_KEY_FILE = config.secretsMasterKeyFilePath;
100	  }
101	  
102	  type MigrationSummary =
103	    | "skipped"
104	    | "already applied"
105	    | "applied (empty database)"
106	    | "applied (pending migrations)";
107	  
108	  function formatPendingMigrationSummary(migrations: string[]): string {
109	    if (migrations.length === 0) return "none";
110	    return migrations.length > 3
111	      ? `${migrations.slice(0, 3).join(", ")} (+${migrations.length - 3} more)`
112	      : migrations.join(", ");
113	  }
114	  
115	  async function promptApplyMigrations(migrations: string[]): Promise<boolean> {
116	    if (process.env.PAPERCLIP_MIGRATION_AUTO_APPLY === "true") return true;
117	    if (process.env.PAPERCLIP_MIGRATION_PROMPT === "never") return false;
118	    if (!stdin.isTTY || !stdout.isTTY) return true;
119	  
120	    const prompt = createInterface({ input: stdin, output: stdout });
121	    try {
122	      const answer = (await prompt.question(
123	        `Apply pending migrations (${formatPendingMigrationSummary(migrations)}) now? (y/N): `,
124	      )).trim().toLowerCase();
125	      return answer === "y" || answer === "yes";
126	    } finally {
127	      prompt.close();
128	    }
129	  }
130	  
131	  type EnsureMigrationsOptions = {
132	    autoApply?: boolean;
133	  };
134	  
135	  async function ensureMigrations(
136	    connectionString: string,
137	    label: string,
138	    opts?: EnsureMigrationsOptions,
139	  ): Promise<MigrationSummary> {
140	    const autoApply = opts?.autoApply === true;
141	    let state = await inspectMigrations(connectionString);
142	    if (state.status === "needsMigrations" && state.reason === "pending-migrations") {
143	      const repair = await reconcilePendingMigrationHistory(connectionString);
144	      if (repair.repairedMigrations.length > 0) {
145	        logger.warn(
146	          { repairedMigrations: repair.repairedMigrations },
147	          `${label} had drifted migration history; repaired migration journal entries from existing schema state.`,
148	        );
149	        state = await inspectMigrations(connectionString);
150	        if (state.status === "upToDate") return "already applied";
151	      }
152	    }
153	    if (state.status === "upToDate") return "already applied";
154	    if (state.status === "needsMigrations" && state.reason === "no-migration-journal-non-empty-db") {
155	      logger.warn(
156	        { tableCount: state.tableCount },
157	        `${label} has existing tables but no migration journal. Run migrations manually to sync schema.`,
158	      );
159	      const apply = autoApply ? true : await promptApplyMigrations(state.pendingMigrations);
160	      if (!apply) {
161	        throw new Error(
162	          `${label} has pending migrations (${formatPendingMigrationSummary(state.pendingMigrations)}). ` +
163	            "Refusing to start against a stale schema. Run pnpm db:migrate or set PAPERCLIP_MIGRATION_AUTO_APPLY=true.",
164	        );
165	      }
166	  
167	      logger.info({ pendingMigrations: state.pendingMigrations }, `Applying ${state.pendingMigrations.length} pending migrations for ${label}`);
168	      await applyPendingMigrations(connectionString);
169	      return "applied (pending migrations)";
170	    }
171	  
172	    const apply = autoApply ? true : await promptApplyMigrations(state.pendingMigrations);
173	    if (!apply) {
174	      throw new Error(
175	        `${label} has pending migrations (${formatPendingMigrationSummary(state.pendingMigrations)}). ` +
176	          "Refusing to start against a stale schema. Run pnpm db:migrate or set PAPERCLIP_MIGRATION_AUTO_APPLY=true.",
177	      );
178	    }
179	  
180	    logger.info({ pendingMigrations: state.pendingMigrations }, `Applying ${state.pendingMigrations.length} pending migrations for ${label}`);
181	    await applyPendingMigrations(connectionString);
182	    return "applied (pending migrations)";
183	  }
184	  
185	  function isLoopbackHost(host: string): boolean {
186	    const normalized = host.trim().toLowerCase();
187	    return normalized === "127.0.0.1" || normalized === "localhost" || normalized === "::1";
188	  }
