190	  function rewriteLocalUrlPort(rawUrl: string | undefined, port: number): string | undefined {
191	    if (!rawUrl) return undefined;
192	    try {
193	      const parsed = new URL(rawUrl);
194	      // The URL API normalizes default ports like :80/:443 to "", so treat them as stable URLs.
195	      if (!parsed.port) return rawUrl;
196	      parsed.port = String(port);
197	      return parsed.toString();
198	    } catch {
199	      return rawUrl;
200	    }
201	  }
202	  
203	  const LOCAL_BOARD_USER_ID = "local-board";
204	  const LOCAL_BOARD_USER_EMAIL = "local@paperclip.local";
205	  const LOCAL_BOARD_USER_NAME = "Board";
206	  
207	  async function ensureLocalTrustedBoardPrincipal(db: any): Promise<void> {
208	    const now = new Date();
209	    const existingUser = await db
210	      .select({ id: authUsers.id })
211	      .from(authUsers)
212	      .where(eq(authUsers.id, LOCAL_BOARD_USER_ID))
213	      .then((rows: Array<{ id: string }>) => rows[0] ?? null);
214	  
215	    if (!existingUser) {
216	      await db.insert(authUsers).values({
217	        id: LOCAL_BOARD_USER_ID,
218	        name: LOCAL_BOARD_USER_NAME,
219	        email: LOCAL_BOARD_USER_EMAIL,
220	        emailVerified: true,
221	        image: null,
222	        createdAt: now,
223	        updatedAt: now,
224	      });
225	    }
226	  
227	    const role = await db
228	      .select({ id: instanceUserRoles.id })
229	      .from(instanceUserRoles)
230	      .where(and(eq(instanceUserRoles.userId, LOCAL_BOARD_USER_ID), eq(instanceUserRoles.role, "instance_admin")))
231	      .then((rows: Array<{ id: string }>) => rows[0] ?? null);
232	    if (!role) {
233	      await db.insert(instanceUserRoles).values({
234	        userId: LOCAL_BOARD_USER_ID,
235	        role: "instance_admin",
236	      });
237	    }
238	  
239	    const companyRows = await db.select({ id: companies.id }).from(companies);
240	    for (const company of companyRows) {
241	      const membership = await db
242	        .select({ id: companyMemberships.id })
243	        .from(companyMemberships)
244	        .where(
245	          and(
246	            eq(companyMemberships.companyId, company.id),
247	            eq(companyMemberships.principalType, "user"),
248	            eq(companyMemberships.principalId, LOCAL_BOARD_USER_ID),
249	          ),
250	        )
251	        .then((rows: Array<{ id: string }>) => rows[0] ?? null);
252	      if (membership) continue;
253	      await db.insert(companyMemberships).values({
254	        companyId: company.id,
255	        principalType: "user",
256	        principalId: LOCAL_BOARD_USER_ID,
257	        status: "active",
258	        membershipRole: "owner",
259	      });
260	    }
261	  }
262	  
263	  let db;
264	  let pluginMigrationDb;
265	  let embeddedPostgres: EmbeddedPostgresInstance | null = null;
266	  let embeddedPostgresStartedByThisProcess = false;
267	  let migrationSummary: MigrationSummary = "skipped";
268	  let activeDatabaseConnectionString: string;
269	  let resolvedEmbeddedPostgresPort: number | null = null;
270	  let startupDbInfo:
271	    | { mode: "external-postgres"; connectionString: string }
272	    | { mode: "embedded-postgres"; dataDir: string; port: number };
273	  if (config.databaseUrl) {
274	    const migrationUrl = config.databaseMigrationUrl ?? config.databaseUrl;
275	    migrationSummary = await ensureMigrations(migrationUrl, "PostgreSQL");
276	  
277	    db = createDb(config.databaseUrl);
278	    pluginMigrationDb = config.databaseMigrationUrl ? createDb(config.databaseMigrationUrl) : db;
279	    logger.info("Using external PostgreSQL via DATABASE_URL/config");
280	    activeDatabaseConnectionString = config.databaseUrl;
281	    startupDbInfo = { mode: "external-postgres", connectionString: config.databaseUrl };
282	  } else {
283	    const moduleName = "embedded-postgres";
284	    let EmbeddedPostgres: EmbeddedPostgresCtor;
285	    try {
286	      const mod = await import(moduleName);
287	      EmbeddedPostgres = mod.default as EmbeddedPostgresCtor;
288	    } catch {
289	      throw new Error(
290	        "Embedded PostgreSQL mode requires dependency `embedded-postgres`. Reinstall dependencies (without omitting required packages), or set DATABASE_URL for external Postgres.",
291	      );
292	    }
293	  
294	    const dataDir = resolve(config.embeddedPostgresDataDir);
295	    const configuredPort = config.embeddedPostgresPort;
296	    let port = configuredPort;
297	    const logBuffer = createEmbeddedPostgresLogBuffer(120);
298	    const verboseEmbeddedPostgresLogs = process.env.PAPERCLIP_EMBEDDED_POSTGRES_VERBOSE === "true";
299	    const appendEmbeddedPostgresLog = (message: unknown) => {
300	      logBuffer.append(message);
301	      if (!verboseEmbeddedPostgresLogs) {
302	        return;
303	      }
304	      const lines = typeof message === "string"
305	        ? message.split(/\r?\n/)
306	        : message instanceof Error
307	          ? [message.message]
308	          : [String(message ?? "")];
309	      for (const lineRaw of lines) {
310	        const line = lineRaw.trim();
311	        if (!line) continue;
312	        logger.info({ embeddedPostgresLog: line }, "embedded-postgres");
313	      }
314	    };
315	    const logEmbeddedPostgresFailure = (phase: "initialise" | "start", err: unknown) => {
316	      const recentLogs = logBuffer.getRecentLogs();
317	      if (recentLogs.length > 0) {
318	        logger.error(
319	          {
320	            phase,
321	            recentLogs,
322	            err,
323	          },
324	          "Embedded PostgreSQL failed; showing buffered startup logs",
325	        );
326	      }
327	    };
328	  
329	    if (config.databaseMode === "postgres") {
330	      logger.warn("Database mode is postgres but no connection string was set; falling back to embedded PostgreSQL");
331	    }
332	  
333	    const clusterVersionFile = resolve(dataDir, "PG_VERSION");
334	    const clusterAlreadyInitialized = existsSync(clusterVersionFile);
335	    const postmasterPidFile = resolve(dataDir, "postmaster.pid");
336	    const isPidRunning = (pid: number): boolean => {
337	      try {
338	        process.kill(pid, 0);
339	        return true;
340	      } catch {
341	        return false;
342	      }
343	    };
344	  
345	    const getRunningPid = (): number | null => {
346	      if (!existsSync(postmasterPidFile)) return null;
347	      try {
348	        const pidLine = readFileSync(postmasterPidFile, "utf8").split("\n")[0]?.trim();
349	        const pid = Number(pidLine);
350	        if (!Number.isInteger(pid) || pid <= 0) return null;
351	        if (!isPidRunning(pid)) return null;
352	        return pid;
353	      } catch {
354	        return null;
355	      }
356	    };
357	  
358	    const runningPid = getRunningPid();
359	    if (runningPid) {
360	      logger.warn(`Embedded PostgreSQL already running; reusing existing process (pid=${runningPid}, port=${port})`);
361	    } else {
362	      const configuredAdminConnectionString = `postgres://paperclip:paperclip@127.0.0.1:${configuredPort}/postgres`;
363	      try {
364	        const actualDataDir = await getPostgresDataDirectory(configuredAdminConnectionString);
365	        if (
366	          typeof actualDataDir !== "string" ||
367	          resolve(actualDataDir) !== resolve(dataDir)
368	        ) {
369	          throw new Error("reachable postgres does not use the expected embedded data directory");
370	        }
371	        await ensurePostgresDatabase(configuredAdminConnectionString, "paperclip");
372	        logger.warn(
373	          `Embedded PostgreSQL appears to already be reachable without a pid file; reusing existing server on configured port ${configuredPort}`,
374	        );
375	      } catch {
376	        const detectedPort = await detectPort(configuredPort);
377	        if (detectedPort !== configuredPort) {
378	          logger.warn(`Embedded PostgreSQL port is in use; using next free port (requestedPort=${configuredPort}, selectedPort=${detectedPort})`);
379	        }
380	        port = detectedPort;
381	        logger.info(`Using embedded PostgreSQL because no DATABASE_URL set (dataDir=${dataDir}, port=${port})`);
382	        embeddedPostgres = new EmbeddedPostgres({
383	          databaseDir: dataDir,
384	          user: "paperclip",
385	          password: "paperclip",
386	          port,
387	          persistent: true,
388	          initdbFlags: ["--encoding=UTF8", "--locale=C", "--lc-messages=C"],
389	          onLog: appendEmbeddedPostgresLog,
390	          onError: appendEmbeddedPostgresLog,
391	        });
392	
393	        if (!clusterAlreadyInitialized) {
394	          try {
395	            await embeddedPostgres.initialise();
396	          } catch (err) {
397	            logEmbeddedPostgresFailure("initialise", err);
398	            throw formatEmbeddedPostgresError(err, {
399	              fallbackMessage: `Failed to initialize embedded PostgreSQL cluster in ${dataDir} on port ${port}`,
400	              recentLogs: logBuffer.getRecentLogs(),
401	            });
402	          }
403	        } else {
404	          logger.info(`Embedded PostgreSQL cluster already exists (${clusterVersionFile}); skipping init`);
405	        }
406	
407	        if (existsSync(postmasterPidFile)) {
408	          logger.warn("Removing stale embedded PostgreSQL lock file");
409	          rmSync(postmasterPidFile, { force: true });
410	        }
411	        try {
412	          await embeddedPostgres.start();
413	        } catch (err) {
414	          logEmbeddedPostgresFailure("start", err);
415	          throw formatEmbeddedPostgresError(err, {
416	            fallbackMessage: `Failed to start embedded PostgreSQL on port ${port}`,
417	            recentLogs: logBuffer.getRecentLogs(),
418	          });
419	        }
420	        embeddedPostgresStartedByThisProcess = true;
421	      }
422	    }
423	  
424	    const embeddedAdminConnectionString = `postgres://paperclip:paperclip@127.0.0.1:${port}/postgres`;
425	    const dbStatus = await ensurePostgresDatabase(embeddedAdminConnectionString, "paperclip");
426	    if (dbStatus === "created") {
427	      logger.info("Created embedded PostgreSQL database: paperclip");
428	    }
429	  
430	    const embeddedConnectionString = `postgres://paperclip:paperclip@127.0.0.1:${port}/paperclip`;
431	    const shouldAutoApplyFirstRunMigrations = !clusterAlreadyInitialized || dbStatus === "created";
432	    if (shouldAutoApplyFirstRunMigrations) {
433	      logger.info("Detected first-run embedded PostgreSQL setup; applying pending migrations automatically");
434	    }
435	    migrationSummary = await ensureMigrations(embeddedConnectionString, "Embedded PostgreSQL", {
436	      autoApply: shouldAutoApplyFirstRunMigrations,
437	    });
438	  
439	    db = createDb(embeddedConnectionString);
440	    pluginMigrationDb = db;
441	    logger.info("Embedded PostgreSQL ready");
442	    activeDatabaseConnectionString = embeddedConnectionString;
443	    resolvedEmbeddedPostgresPort = port;
444	    startupDbInfo = { mode: "embedded-postgres", dataDir, port };
445	  }
446	  
447	  if (config.deploymentMode === "local_trusted" && !isLoopbackHost(config.host)) {
448	    throw new Error(
449	      `local_trusted mode requires loopback host binding (received: ${config.host}). ` +
450	        "Use authenticated mode for non-loopback deployments.",
451	    );
452	  }
453	  
454	  if (config.deploymentMode === "local_trusted" && config.deploymentExposure !== "private") {
455	    throw new Error("local_trusted mode only supports private exposure");
456	  }
457	  
458	  if (config.deploymentMode === "authenticated") {
459	    if (config.authBaseUrlMode === "explicit" && !config.authPublicBaseUrl) {
460	      throw new Error("auth.baseUrlMode=explicit requires auth.publicBaseUrl");
461	    }
462	    if (config.deploymentExposure === "public") {
463	      if (config.authBaseUrlMode !== "explicit") {
464	        throw new Error("authenticated public exposure requires auth.baseUrlMode=explicit");
465	      }
466	      if (!config.authPublicBaseUrl) {
467	        throw new Error("authenticated public exposure requires auth.publicBaseUrl");
468	      }
469	    }
470	  }
471	
472	  const requestedListenPort = config.port;
473	  const listenPort = await detectPort(requestedListenPort);
474	  if (config.authBaseUrlMode === "explicit" && config.authPublicBaseUrl) {
475	    config.authPublicBaseUrl = rewriteLocalUrlPort(config.authPublicBaseUrl, listenPort);
476	  }
477	  
478	  let authReady = config.deploymentMode === "local_trusted";
479	  let betterAuthHandler: RequestHandler | undefined;
480	  let resolveSession:
481	    | ((req: ExpressRequest) => Promise<BetterAuthSessionResult | null>)
482	    | undefined;
483	  let resolveSessionFromHeaders:
484	    | ((headers: Headers) => Promise<BetterAuthSessionResult | null>)
485	    | undefined;
486	  if (config.deploymentMode === "local_trusted") {
487	    await ensureLocalTrustedBoardPrincipal(db as any);
488	  }
489	  if (config.deploymentMode === "authenticated") {
490	    const {
491	      createBetterAuthHandler,
492	      createBetterAuthInstance,
493	      deriveAuthTrustedOrigins,
494	      resolveBetterAuthSession,
495	      resolveBetterAuthSessionFromHeaders,
496	    } = await import("./auth/better-auth.js");
497	    const derivedTrustedOrigins = deriveAuthTrustedOrigins(config, { listenPort });
498	    const envTrustedOrigins = (process.env.BETTER_AUTH_TRUSTED_ORIGINS ?? "")
499	      .split(",")
500	      .map((value) => value.trim())
501	      .filter((value) => value.length > 0);
502	    const effectiveTrustedOrigins = Array.from(new Set([...derivedTrustedOrigins, ...envTrustedOrigins]));
503	    logger.info(
504	      {
505	        authBaseUrlMode: config.authBaseUrlMode,
506	        authPublicBaseUrl: config.authPublicBaseUrl ?? null,
507	        trustedOrigins: effectiveTrustedOrigins,
508	        trustedOriginsSource: {
509	          derived: derivedTrustedOrigins.length,
510	          env: envTrustedOrigins.length,
511	        },
512	      },
513	      "Authenticated mode auth origin configuration",
514	    );
515	    const auth = createBetterAuthInstance(db as any, config, effectiveTrustedOrigins);
516	    betterAuthHandler = createBetterAuthHandler(auth);
517	    resolveSession = (req) => resolveBetterAuthSession(auth, req);
518	    resolveSessionFromHeaders = (headers) => resolveBetterAuthSessionFromHeaders(auth, headers);
519	    await initializeBoardClaimChallenge(db as any, { deploymentMode: config.deploymentMode });
520	    authReady = true;
521	  }
522	
523	  if (resolvedEmbeddedPostgresPort !== null && resolvedEmbeddedPostgresPort !== config.embeddedPostgresPort) {
524	    config.embeddedPostgresPort = resolvedEmbeddedPostgresPort;
525	  }
526	  maybePersistWorktreeRuntimePorts({
527	    serverPort: listenPort,
528	    databasePort: resolvedEmbeddedPostgresPort,
529	  });
530	  const uiMode = config.uiDevMiddleware ? "vite-dev" : config.serveUi ? "static" : "none";
531	  const storageService = createStorageServiceFromConfig(config);
532	  const feedback = feedbackService(db as any, {
533	    shareClient: createFeedbackTraceShareClientFromConfig(config),
534	  });
535	  const backupSettingsSvc = instanceSettingsService(db);
536	  let databaseBackupInFlight = false;
537	  const runServerDatabaseBackup = async (
538	    trigger: InstanceDatabaseBackupTrigger,
539	  ): Promise<InstanceDatabaseBackupRunResult | null> => {
540	    if (databaseBackupInFlight) {
541	      const message = "Database backup already in progress";
542	      if (trigger === "scheduled") {
543	        logger.warn("Skipping scheduled database backup because a previous backup is still running");
544	        return null;
545	      }
546	      throw conflict(message);
547	    }
548	
549	    databaseBackupInFlight = true;
550	    const startedAt = new Date();
551	    const startedAtMs = Date.now();
552	    const label = trigger === "scheduled" ? "Automatic" : "Manual";
553	    try {
554	      logger.info({ backupDir: config.databaseBackupDir, trigger }, `${label} database backup starting`);
555	      // Read retention from Instance Settings (DB) so changes take effect without restart.
556	      const generalSettings = await backupSettingsSvc.getGeneral();
557	      const retention = generalSettings.backupRetention;
558	
559	      const result = await runDatabaseBackup({
560	        connectionString: activeDatabaseConnectionString,
561	        backupDir: config.databaseBackupDir,
562	        retention,
563	        filenamePrefix: "paperclip",
564	      });
565	      const finishedAt = new Date();
566	      const response: InstanceDatabaseBackupRunResult = {
567	        ...result,
568	        trigger,
569	        backupDir: config.databaseBackupDir,
